local PigeonCourier = {}
local PRODUCTS = {
    homing_pigeon = { name = "Domovračni golob", pigeonCost = 1, grainCost = 1, time = 2, cost = 20, speed = 40, description = "Domovračni golob za pošto." },
    racing_pigeon = { name = "Dirkalni golob", pigeonCost = 1, grainCost = 1, time = 3, cost = 40, speed = 55, prestige = 2, description = "Dirkalni golob za hitra sporočila." },
    messenger_pigeon = { name = "Kurirski golob", pigeonCost = 1, grainCost = 1, silverCost = 1, time = 5, cost = 100, speed = 70, prestige = 5, happiness = 1, description = "Kurirski golob za tajne sporazume." },
    silver_banded_pigeon = { name = "Srebrno obročkasti golob", pigeonCost = 1, silverCost = 1, grainCost = 1, time = 7, cost = 240, speed = 82, prestige = 10, happiness = 2, description = "Srebrno obročkasti golob za plemiče." },
    silver_caged_pigeon = { name = "Srebrno kletki golob", pigeonCost = 1, silverCost = 1, grainCost = 1, time = 10, cost = 520, speed = 90, prestige = 16, happiness = 3, description = "Golob iz srebrne kletke za visoke plemiče." },
    royal_grand_pigeon = { name = "Kraljevski veliki golob", pigeonCost = 2, goldCost = 1, silverCost = 1, jewelCost = 1, grainCost = 2, time = 15, cost = 1500, speed = 100, prestige = 38, happiness = 8, description = "Veliki kraljevski golob z zlatom in dragulji za kronanje." },
}
local BUILDINGS = {
    workshop = { name = "Golobja postaja", cost = { gold = 220, wood = 120, stone = 150 }, upkeep = 5, qualityBonus = 5 },
    pigeon_loft = { name = "Golobnjak", cost = { gold = 800, wood = 250, stone = 300, grain = 10 }, upkeep = 20, qualityBonus = 18 },
    message_house = { name = "Sporočilnica", cost = { gold = 2100, wood = 350, stone = 600, silver = 25, leather = 8 }, upkeep = 52, qualityBonus = 30 },
    royal_pigeon_atelier = { name = "Kraljevski atelje golobarstva", cost = { gold = 8500, wood = 600, stone = 900, gold = 60, jewel = 20 }, upkeep = 170, qualityBonus = 55, prestigeBonus = 40 },
}
PigeonCourier.pigeonStock = 22; PigeonCourier.grainStock = 22; PigeonCourier.silverStock = 8; PigeonCourier.goldStock = 6; PigeonCourier.jewelStock = 6
PigeonCourier.productStock = {}; PigeonCourier.buildings = {}; PigeonCourier.maker = nil; PigeonCourier.activeMaking = {}; PigeonCourier.totalProducts = 0; PigeonCourier.dayTimer = 0
function PigeonCourier.init() PigeonCourier.pigeonStock=22; PigeonCourier.grainStock=22; PigeonCourier.silverStock=8; PigeonCourier.goldStock=6; PigeonCourier.jewelStock=6; PigeonCourier.productStock={}; PigeonCourier.buildings={}; PigeonCourier.maker=nil; PigeonCourier.activeMaking={}; PigeonCourier.totalProducts=0; PigeonCourier.dayTimer=0; print("[PigeonCourier] Royal Pigeon Courier System initialized (6 products, 4 buildings)") end
function PigeonCourier.hireMaker(n,s) s=s or math.random(45,85); local c=470+s*10; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; PigeonCourier.maker={name=n or ("Golobar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Golobar najet: %s (spretnost: %d)",PigeonCourier.maker.name,s),"success") end; return true end
function PigeonCourier.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function PigeonCourier.build(id) local ok,e=PigeonCourier.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(PigeonCourier.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function PigeonCourier.getQualityBonus() local b=0; for _,bd in ipairs(PigeonCourier.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function PigeonCourier.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.pigeonCost and PigeonCourier.pigeonStock<(d.pigeonCost or 0) then return false,"Premalo golobov" end; if d.grainCost and PigeonCourier.grainStock<(d.grainCost or 0) then return false,"Premalo žita" end; if d.silverCost and PigeonCourier.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and PigeonCourier.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and PigeonCourier.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if #PigeonCourier.buildings==0 then return false,"Potrebna delavnica" end; if not PigeonCourier.maker then return false,"Potreben golobar" end; return true end
function PigeonCourier.make(pt,qty) qty=qty or 1; local ok,e=PigeonCourier.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.pigeonCost then PigeonCourier.pigeonStock=PigeonCourier.pigeonStock-d.pigeonCost*qty end; if d.grainCost then PigeonCourier.grainStock=PigeonCourier.grainStock-d.grainCost*qty end; if d.silverCost then PigeonCourier.silverStock=PigeonCourier.silverStock-d.silverCost*qty end; if d.goldCost then PigeonCourier.goldStock=PigeonCourier.goldStock-d.goldCost*qty end; if d.jewelCost then PigeonCourier.jewelStock=PigeonCourier.jewelStock-d.jewelCost*qty end; local t=d.time; if PigeonCourier.maker then t=math.max(1,t-math.floor(PigeonCourier.maker.skill/12)) end; table.insert(PigeonCourier.activeMaking,{id="pigeon_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,speed=d.speed or 0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function PigeonCourier.completeMaking(m) local q=1.0+(PigeonCourier.getQualityBonus()/100); if PigeonCourier.maker then q=q+(PigeonCourier.maker.skill/180) end; q=math.min(2.0,q); PigeonCourier.productStock[m.productType]=(PigeonCourier.productStock[m.productType] or 0)+m.quantity; PigeonCourier.totalProducts=PigeonCourier.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if PigeonCourier.maker then PigeonCourier.maker.itemsMade=PigeonCourier.maker.itemsMade+m.quantity; if math.random()<0.20 then PigeonCourier.maker.skill=math.min(100,PigeonCourier.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Golob vzrejen: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"pigeon.completed",{productName=m.productName,speed=m.speed,prestige=m.prestige,happiness=m.happiness}) end end
function PigeonCourier.update(dt) if not _G.state then return end; PigeonCourier.dayTimer=PigeonCourier.dayTimer+dt; if PigeonCourier.dayTimer>=30 then PigeonCourier.dayTimer=0; for i=#PigeonCourier.activeMaking,1,-1 do local m=PigeonCourier.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then PigeonCourier.completeMaking(m); table.remove(PigeonCourier.activeMaking,i) end end; local tu=0; for _,bd in ipairs(PigeonCourier.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if PigeonCourier.maker then tu=tu+12 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function PigeonCourier.getStats() return {pigeonStock=PigeonCourier.pigeonStock,grainStock=PigeonCourier.grainStock,silverStock=PigeonCourier.silverStock,goldStock=PigeonCourier.goldStock,jewelStock=PigeonCourier.jewelStock,productStock=PigeonCourier.productStock,numBuildings=#PigeonCourier.buildings,hasMaker=PigeonCourier.maker~=nil,makerName=PigeonCourier.maker and PigeonCourier.maker.name or "—",makerSkill=PigeonCourier.maker and PigeonCourier.maker.skill or 0,activeMaking=#PigeonCourier.activeMaking,totalProducts=PigeonCourier.totalProducts} end
return PigeonCourier
